using var dbContext = new AppDbContext();

// Compile the query once at startup
static readonly Func<AppDbContext, int, Task<Product?>> GetProductById =
    EF.CompileQuery((AppDbContext ctx, int id) =>
        ctx.Products.FirstOrDefault(p => p.Id == id));

// Reuse it throughout the application lifetime
Product? product = await GetProductById(dbContext, productId);

static readonly Func<AppDbContext, int, Task<Product?>> GetProductByIdAsync =
    EF.CompileAsyncQuery((AppDbContext ctx, int id) =>
        ctx.Products.FirstOrDefault(p => p.Id == id));

Product? product = await GetProductByIdAsync(dbContext, productId);

